const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ROLES=['Frontend','Backend','Fullstack','Mobile','Data / ML','DevOps','Design'];
const LS=k=>{try{return localStorage.getItem(k)}catch{return null}},LSet=(k,v)=>{try{localStorage.setItem(k,v)}catch{}};
const S={db:null,me:null,profiles:[],stars:{},msgs:{},st:{},reg:{step:0,d:{}},ctab:'dev',cq:'',rev:{},bf:'all',lang:LS('lang')==='en'?'en':'ru',theme:LS('theme')==='light'?'light':'dark',loaded:false,q:'',tech:'',sort:'new',dq:'',role:'',edit:null,sure:null};
const mine=()=>S.me&&S.profiles.find(p=>p.id===S.me.id);
const projects=()=>S.profiles.flatMap(p=>(p.projects||[]).map(x=>({...x,owner:p})));
const sc=id=>Object.values(S.stars).filter(a=>a.includes(id)).length;
const safe=u=>/^https?:\/\//i.test(u||'')?esc(u):'';
const lnk=(u,l,c='')=>safe(u)?`<a class="btn ${c}" target="_blank" rel="noopener" href="${safe(u)}">${l} ↗</a>`:'';
const tags=a=>`<div class="tags">${(a||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`;
const hue=s=>[...s].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,7)%360;
const tl=s=>[...new Set(s.split(',').map(x=>x.trim()).filter(Boolean))].slice(0,10);
const cover=(p,c='')=>/^data:image\/jpeg;base64,[A-Za-z0-9+\/=]+$/.test(p.cover||'')?`<div class="cover ${c}" style="background-image:url(${p.cover})"></div>`:`<div class="cover gen ${c}" style="--h:${hue(p.title)}"><span>${esc(p.title.slice(0,2))}</span></div>`;
const card=p=>`<a class="card" href="#project-${esc(p.id)}">${cover(p)}<div class="cb"><h3>${esc(p.title)}</h3><p>${esc(p.desc.slice(0,100))}</p>${tags((p.tech||[]).slice(0,4))}<div class="by"><span>@${esc(p.owner.username)}</span><span>★ ${sc(p.id)}</span></div></div></a>`;
const devCard=p=>`<a class="card dev" href="#dev-${esc(p.username)}">${avh(p)}<div><b>${esc(p.name||p.username)}</b><div class="mt sm">@${esc(p.username)} · ${esc(p.role||'Developer')}${p.open?' · <span class="ok">Открыт к работе</span>':''}${rv(p.id).length?' · ★ '+avg(p.id):''}</div>${tags((p.skills||[]).slice(0,3))}</div></a>`;
const devs=()=>S.profiles.filter(p=>p.username&&p.type!=='client'&&(!S.role||p.role===S.role)&&(!S.dq||(p.name+' '+p.username+' '+(p.skills||[]).join(' ')).toLowerCase().includes(S.dq.toLowerCase())));
const devRes=()=>devs().map(devCard).join('')||`<p class="mt">${i18n('Никого не нашли')}</p>`;
const filt=()=>projects().filter(p=>(!S.tech||(p.tech||[]).includes(S.tech))&&(!S.q||(p.title+' '+p.desc).toLowerCase().includes(S.q.toLowerCase()))).sort(S.sort==='pop'?(a,b)=>sc(b.id)-sc(a.id):S.sort==='az'?(a,b)=>a.title.localeCompare(b.title):(a,b)=>b.created-a.created);
const catRes=()=>filt().map(card).join('')||`<p class="mt">${i18n('Ничего не найдено')}</p>`;
const nf=m=>`<section class="w sec"><div class="box ctr"><b>${m}</b><br><br><a class="btn" href="#home">На главную</a></div></section>`;
const foot='<footer><b>DEVFOLIO</b><span>Публикуйте проекты. Делитесь одной ссылкой.</span></footer>';

const homeV=()=>{const P=projects(),pop=[...P].sort((a,b)=>sc(b.id)-sc(a.id)||b.created-a.created).slice(0,3),rec=[...P].sort((a,b)=>b.created-a.created).slice(0,6);
return `<section class="w hero"><div class="eb">Портфолио для разработчиков</div><h1>Одна ссылка —<br>всё ваше портфолио</h1><p class="lead">Публикуйте проекты, оформляйте профиль и отправляйте работодателю страницу, которая показывает работу, а не резюме.</p><div class="row"><a class="btn pri" href="#dashboard">Создать профиль</a><a class="btn" href="#catalog">Смотреть проекты</a></div><div class="mt sm">${S.profiles.filter(p=>p.username&&p.type!=='client').length} разработчиков · ${P.length} проектов</div></section>
<section class="w sec" id="find"><h2>Найти разработчика</h2><input id="dq" placeholder="Имя, username или технология" value="${esc(S.dq)}"><div id="devres" class="grid g3">${devRes()}</div></section><section class="w sec"><div class="hd"><h2>Категории разработчиков</h2><a class="mt" href="#categories">Все категории →</a></div><div class="grid g3">${ROLES.map(catCard).join('')}</div></section>
${P.length?`<section class="w sec"><h2>Популярные проекты</h2><div class="grid">${pop.map(card).join('')}</div></section><section class="w sec"><div class="hd"><h2>Недавно опубликованные</h2><a class="mt" href="#catalog">Весь каталог →</a></div><div class="grid">${rec.map(card).join('')}</div></section>`:`<section class="w sec"><div class="box ctr"><b>Пока нет проектов</b><p class="mt">Станьте первым — опубликуйте проект в личном кабинете.</p><br><a class="btn pri" href="#dashboard">Опубликовать проект</a></div></section>`}
<section class="w sec"><h2>Почему DEVFOLIO</h2><div class="grid g3">${[['Показ, а не рассказ','Крупные превью, стек и живые демо вместо списка навыков.'],['Одна ссылка','Публичная страница профиля с проектами и контактами.'],['Быстрый поиск','Фильтры по технологиям, поиск по людям и проектам.']].map(x=>`<div class="box"><b>${x[0]}</b><p class="mt">${x[1]}</p></div>`).join('')}</div></section>`};

const catalogV=()=>{const tc={};projects().forEach(p=>(p.tech||[]).forEach(t=>tc[t]=(tc[t]||0)+1));const top=Object.keys(tc).sort((a,b)=>tc[b]-tc[a]).slice(0,14);
return `<section class="w sec"><h1 class="s">Каталог проектов</h1><div class="row"><input id="q" placeholder="Поиск по названию" value="${esc(S.q)}"><select id="sort"><option value="new">Сначала новые</option><option value="pop"${S.sort==='pop'?' selected':''}>Популярные</option><option value="az"${S.sort==='az'?' selected':''}>По алфавиту</option></select></div><div class="chips"><button class="chip${S.tech?'':' on'}" data-act="tech" data-v="">Все</button>${top.map(t=>`<button class="chip${S.tech===t?' on':''}" data-act="tech" data-v="${esc(t)}">${esc(t)}</button>`).join('')}</div><div id="res" class="grid">${catRes()}</div></section>`};

const devV=u=>{const p=S.profiles.find(x=>x.username===u);if(!p)return nf('Профиль не найден');
return `<section class="w sec"><div class="ph"><div class="av lg">${esc((p.name||u)[0].toUpperCase())}</div><div><h1 class="s">${esc(p.name||u)}</h1><div class="mt">@${esc(p.username)} · ${esc(p.role||'Developer')}</div></div><span class="sp"></span>${S.me&&p.id===S.me.id?'<a class="btn" href="#dashboard">Редактировать</a>':''}</div><p class="lead">${esc(p.bio||'')}</p>${tags(p.skills)}<div class="row">${lnk(p.github,'GitHub')}${lnk(p.site,'Сайт')}${p.email?`<a class="btn" href="mailto:${esc(p.email)}">Написать</a>`:''}${S.me&&p.id===S.me.id?'':`<a class="btn pri" href="#chat-${esc(p.username)}">Сообщение</a>`}</div></section><section class="w sec"><h2>Проекты</h2><div class="grid">${(p.projects||[]).map(x=>card({...x,owner:p})).join('')||'<p class="mt">Пока нет проектов</p>'}</div></section>`};

const projV=id=>{const p=projects().find(x=>x.id===id);if(!p)return nf('Проект не найден');const o=p.owner,st=(S.stars[S.me?.id]||[]).includes(id),more=(o.projects||[]).filter(x=>x.id!==id);
return `<section class="w sec"><a class="mt" href="#catalog">← Каталог</a>${cover(p,'big')}<div class="pg"><div><h1 class="s">${esc(p.title)}</h1><p class="lead" style="white-space:pre-line">${esc(p.desc)}</p>${tags(p.tech)}<div class="row">${lnk(p.demo,'Live Demo','pri')}${lnk(p.repo,'GitHub')}<button class="btn${st?' on':''}" data-act="star" data-v="${esc(id)}">${st?'★':'☆'} ${sc(id)}</button></div></div><a class="box" href="#dev-${esc(o.username)}">${avh(o)}<br><b>${esc(o.name||o.username)}</b><div class="mt sm">@${esc(o.username)}</div><p class="mt sm">${esc((o.bio||'').slice(0,120))}</p></a></div></section>${more.length?`<section class="w sec"><h2>Другие проекты автора</h2><div class="grid">${more.map(x=>card({...x,owner:o})).join('')}</div></section>`:''}`};

const v=x=>esc(x||'');
const pf=m=>`<form data-f="profile"><div class="fg"><div><label>Username (ссылка @username)</label><input name="username" required maxlength="20" value="${v(m?.username)}"></div><div><label>Имя</label><input name="name" maxlength="60" value="${v(m?.name||S.me.name)}"></div><div><label>Направление</label><select name="role">${ROLES.map(r=>`<option${m?.role===r?' selected':''}>${r}</option>`).join('')}</select></div><div><label>Навыки (через запятую)</label><input name="skills" value="${v((m?.skills||[]).join(', '))}"></div><div class="full"><label>О себе</label><textarea name="bio" rows="3" maxlength="500">${v(m?.bio)}</textarea></div><div><label>GitHub (ссылка)</label><input name="github" value="${v(m?.github)}"></div><div><label>Сайт (ссылка)</label><input name="site" value="${v(m?.site)}"></div><div class="full"><label>Контактный email</label><input name="email" value="${v(m?.email)}"></div><div class="full"><label class="ck"><input type="checkbox" name="open"${m?.open?' checked':''}> Открыт к работе</label></div></div><div class="row"><button class="btn pri">Сохранить профиль</button></div></form>`;
const jf=x=>`<form class="box" data-f="project"><input type="hidden" name="id" value="${v(x?.id)}"><div class="fg"><div class="full"><label>Название</label><input name="title" required maxlength="80" value="${v(x?.title)}"></div><div class="full"><label>Описание</label><textarea name="desc" rows="4" required maxlength="2000">${v(x?.desc)}</textarea></div><div class="full"><label>Технологии (через запятую)</label><input name="tech" value="${v((x?.tech||[]).join(', '))}"></div><div><label>Live Demo (ссылка)</label><input name="demo" value="${v(x?.demo)}"></div><div><label>GitHub (ссылка)</label><input name="repo" value="${v(x?.repo)}"></div><div class="full"><label>Изображение проекта${x?.cover?' (оставьте пустым, чтобы сохранить текущее)':''}</label><input type="file" name="cv" accept="image/*"></div></div><div class="row"><button class="btn pri">Сохранить проект</button><button type="button" class="btn" data-act="cancel">Отмена</button></div></form>`;
const dashV=()=>{if(!S.db||!S.me)return `<section class="w sec"><div class="box ctr"><h1 class="s">Личный кабинет</h1><p class="mt">Вход выполняется через ваш аккаунт claude.ai — отдельный пароль не нужен. Откройте страницу, находясь в аккаунте, и вы сможете создать профиль и публиковать проекты.</p></div></section>`;
const m=mine();if(!m)return regV2();if(m.type==='client')return dashC(m);
const url=location.href.split('#')[0]+'#dev-'+m.username,fav=projects().filter(p=>(S.stars[S.me.id]||[]).includes(p.id)),ed=S.edit&&(S.edit==='new'?{}:(m.projects||[]).find(p=>p.id===S.edit));
return `<section class="w sec"><h1 class="s">Личный кабинет</h1><div class="box"><div class="mt sm">Ваша публичная ссылка</div><b style="word-break:break-all">${esc(url)}</b><div class="row"><button class="btn" data-act="copy">Скопировать</button><a class="btn" href="#dev-${esc(m.username)}">Открыть профиль</a></div></div><details><summary>Настройки профиля</summary>${pf2(m)}</details></section>
<section class="w sec"><div class="hd"><h2>Мои проекты</h2><button class="btn pri sm" data-act="newp">+ Добавить проект</button></div>${ed?jf(ed):''}${(m.projects||[]).map(p=>`<div class="pr"><b>${esc(p.title)}</b><a class="btn sm" href="#project-${esc(p.id)}">Открыть</a><button class="btn sm" data-act="edit" data-v="${esc(p.id)}">Изменить</button><button class="btn sm dg" data-act="del" data-v="${esc(p.id)}">${S.sure===p.id?'Точно удалить?':'Удалить'}</button></div>`).join('')||(ed?'':'<p class="mt">Проектов пока нет — добавьте первый.</p>')}</section>
<section class="w sec"><h2>Избранное</h2><div class="grid">${fav.map(card).join('')||'<p class="mt">Нажмите ☆ на странице проекта, чтобы сохранить его здесь.</p>'}</div></section>`};

const so=t=>`<section class="w sec"><div class="box ctr" style="max-width:560px;margin:auto"><h1 class="s">${t}</h1><p class="mt">Вход выполняется через ваш аккаунт claude.ai — отдельный пароль не нужен. Откройте страницу, находясь в аккаунте.</p></div></section>`;
const ucheck=u=>{u=(u||'').trim().toLowerCase();return !u?'':!/^[a-z0-9_]{3,20}$/.test(u)?'3–20 символов: a–z, 0–9, _':S.profiles.some(p=>p.username===u)?'Занято':'Свободно ✓'};
const when=t=>new Date(t).toLocaleString(S.lang,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const thread=o=>[...(S.msgs[S.me.id]||[]).filter(m=>m.to===o).map(m=>({...m,me:1})),...(S.msgs[o]||[]).filter(m=>m.to===S.me.id)].sort((a,b)=>a.t-b.t);
const partners=()=>{if(!S.me)return [];const s=new Set((S.msgs[S.me.id]||[]).map(m=>m.to));Object.entries(S.msgs).forEach(([u,l])=>{if(u!==S.me.id&&l.some(m=>m.to===S.me.id))s.add(u)});return [...s].map(id=>({id,p:S.profiles.find(x=>x.id===id),th:thread(id)})).filter(x=>x.th.length&&x.p?.username).map(x=>({...x,un:x.th.filter(m=>!m.me&&m.t>(S.st.read?.[x.id]||0)).length,last:x.th[x.th.length-1]})).sort((a,b)=>b.last.t-a.last.t)};
const unread=()=>partners().reduce((n,x)=>n+x.un,0);
const starEv=()=>{const ids=new Set((mine()?.projects||[]).map(p=>p.id)),o=[];Object.entries(S.stars).forEach(([u,a])=>{if(u!==S.me?.id)a.forEach(pid=>{if(ids.has(pid))o.push({k:u+':'+pid,u,pid})})});return o};
const newStars=()=>{const s=new Set(S.st.seen||[]);return S.me?starEv().filter(e=>!s.has(e.k)):[]};
const bell=()=>partners().filter(x=>x.un).length+newStars().length+newRev().length;
const updAcc=()=>{$('#acc').innerHTML=!S.me?'<a class="btn sm pri" href="#register">Войти</a>':!S.loaded?'':!mine()?'<a class="btn sm pri" href="#register">Регистрация</a>':`<a class="ic" href="#messages" title="Сообщения">✉${unread()?`<b>${unread()}</b>`:''}</a><a class="ic" href="#notifications" title="Уведомления">🔔${bell()?`<b>${bell()}</b>`:''}</a><a class="btn sm" href="#dashboard">${esc(S.me.name)}</a>`};
async function stSave(p){try{await S.db.doc('data/users/'+S.me.id+'/state').set({...S.st,...p})}catch(e){toast(e.message||'Ошибка',1)}}
function afterRender(h){updAcc();updTop();trNode(document.body);if(h.startsWith('chat-')&&S.me&&S.db){const o=S.profiles.find(p=>p.username===h.slice(5));if(o){const t=$('#thread');if(t)t.scrollTop=t.scrollHeight;const last=Math.max(0,...thread(o.id).filter(m=>!m.me).map(m=>m.t));if(last>(S.st.read?.[o.id]||0))stSave({read:{...S.st.read,[o.id]:last}})}}}
const regV=()=>{if(!S.db||!S.me)return so('Регистрация');const r=S.reg,d=r.d,st=r.step;
const f=[`<label>Username — ваша ссылка @username</label><input name="username" required maxlength="20" autocomplete="off" value="${v(d.username)}"><div class="sm mt" id="uc">${ucheck(d.username)}</div><label>Имя</label><input name="name" maxlength="60" value="${v(d.name||S.me.name)}">`,`<label>Направление</label><select name="role">${ROLES.map(x=>`<option${d.role===x?' selected':''}>${x}</option>`).join('')}</select><label>Навыки (через запятую)</label><input name="skills" value="${v(d.skills)}"><label>О себе</label><textarea name="bio" rows="4" maxlength="500">${v(d.bio)}</textarea>`,`<label>GitHub (ссылка)</label><input name="github" value="${v(d.github)}"><label>Сайт (ссылка)</label><input name="site" value="${v(d.site)}"><label>Контактный email</label><input name="email" value="${v(d.email)}"><label class="ck" style="margin-top:14px"><input type="checkbox" name="open"${d.open?' checked':''}> Открыт к работе</label>`][st];
return `<section class="w sec"><div class="box" style="max-width:560px;margin:auto"><div class="eb">Шаг ${st+1} из 3</div><div class="bar"><i style="width:${(st+1)*33.4}%"></i></div><h1 class="s">Создайте профиль</h1><form data-f="reg">${f}<div class="row">${st?'<button type="button" class="btn" data-act="back">Назад</button>':''}<button class="btn pri">${st===2?'Создать профиль':'Далее'}</button></div></form></div></section>`};
const msgsV=()=>{if(!S.me||!S.db)return so('Сообщения');const L=partners();
return `<section class="w sec"><h1 class="s">Сообщения</h1><p class="mt sm">Сообщения хранятся в общей базе страницы и технически доступны её владельцу — не отправляйте пароли и личные данные.</p><br>${L.map(x=>`<a class="box pr2" href="#chat-${esc(x.p.username)}"><div class="av">${esc((x.p.name||'?')[0].toUpperCase())}</div><div class="fl"><b>${esc(x.p.name||x.p.username)}</b><div class="mt sm">${esc(x.last.text.slice(0,70))}</div></div><span class="mt sm">${when(x.last.t)}</span>${x.un?`<b class="dot">${x.un}</b>`:''}</a>`).join('')||'<div class="box ctr"><b>Сообщений пока нет</b><p class="mt">Откройте профиль разработчика и нажмите «Сообщение».</p><br><a class="btn pri" href="#home">Найти разработчика</a></div>'}</section>`};
const threadHtml=u=>{const o=S.profiles.find(p=>p.username===u);return o?thread(o.id).map(m=>`<div class="m${m.me?' me':''}"><div>${esc(m.text)}</div><span>${when(m.t)}</span></div>`).join('')||'<p class="mt sm ctr">Напишите первое сообщение</p>':''};
const chatV=u=>{if(!S.me||!S.db)return so('Сообщения');const o=S.profiles.find(p=>p.username===u);if(!o)return nf('Пользователь не найден');if(o.id===S.me.id)return nf('Это ваш профиль');
return `<section class="w sec"><div style="max-width:680px;margin:auto"><a class="mt" href="#messages">← Сообщения</a><div class="ph" style="margin:14px 0 0"><div class="av">${esc((o.name||u)[0].toUpperCase())}</div><a href="#dev-${esc(u)}"><b>${esc(o.name||u)}</b><div class="mt sm">@${esc(u)}</div></a></div><div id="thread" class="th">${threadHtml(u)}</div><form data-f="msg" data-u="${esc(u)}" class="row" style="margin:0"><textarea id="mt" name="text" rows="2" maxlength="1000" placeholder="Сообщение"></textarea><button class="btn pri">Отправить</button></form><p class="mt sm">Общая база страницы: не отправляйте пароли и личные данные.</p></div></section>`};
const notifV=()=>{if(!S.me||!S.db)return so('Уведомления');const L=partners().filter(x=>x.un),ns=newStars(),seen=new Set(S.st.seen||[]),old=starEv().filter(e=>seen.has(e.k));
const star=(e,n)=>{const p=projects().find(x=>x.id===e.pid),u=S.profiles.find(x=>x.id===e.u);return p?`<a class="box pr2" href="#project-${esc(e.pid)}"><span>★</span><div class="fl"><b>${esc(u?.name||'Кто-то')}</b> добавил(а) в избранное «${esc(p.title)}»</div>${n?'<b class="dot">new</b>':''}</a>`:''};
return `<section class="w sec"><div class="hd"><h1 class="s">Уведомления</h1>${L.length||ns.length||newRev().length?'<button class="btn sm" data-act="readall">Отметить прочитанным</button>':''}</div>${L.map(x=>`<a class="box pr2" href="#chat-${esc(x.p.username)}"><span>✉</span><div class="fl"><b>${esc(x.p.name||x.p.username)}</b>: новых сообщений — ${x.un}<div class="mt sm">${esc(x.last.text.slice(0,70))}</div></div><b class="dot">new</b></a>`).join('')}${newRev().map(revN).join('')}${ns.map(e=>star(e,1)).join('')}${old.map(e=>star(e,0)).join('')}${L.length||ns.length||old.length||newRev().length?'':'<div class="box ctr"><b>Пока тихо</b><p class="mt">Здесь появятся новые сообщения и добавления ваших проектов в избранное.</p></div>'}</section>`};
