const RX=[[/^оставил\(а\) отзыв: ([★☆]+)$/,'left a review: $1'],[/^(\d+) разработчик(?:а|ов)?$/,(m,n)=>n+(n==1?' developer':' developers')],[/^(\d+) разработчиков · (\d+) проектов$/,'$1 developers · $2 projects'],[/^Шаг (\d) из (\d)$/,'Step $1 of $2'],[/^: новых сообщений — (\d+)$/,': $1 new messages'],[/^добавил\(а\) в избранное «([\s\S]*)»$/,'added “$1” to favorites']];
const i18n=s=>{if(S.lang!=='en'||typeof s!=='string')return s;const m=s.match(/^(\s*)([\s\S]*?)(\s*)$/),k=m[2];let r=I[k];if(r===undefined)for(const[x,y]of RX)if(x.test(k)){r=k.replace(x,y);break}return r===undefined?s:m[1]+r+m[3]};
const trNode=root=>{if(S.lang!=='en')return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){const r=i18n(n.nodeValue);if(r!==n.nodeValue)n.nodeValue=r}root.querySelectorAll('[placeholder],[title]').forEach(e=>['placeholder','title'].forEach(a=>{if(e.hasAttribute(a))e.setAttribute(a,i18n(e.getAttribute(a)))}))};
