const imgOk=s=>/^data:image\/jpeg;base64,[A-Za-z0-9+\/=]+$/.test(s||'');
const avh0=(p,c='')=>imgOk(p.avatar)?`<div class="av ${c}" style="background-image:url(${p.avatar});background-size:cover;background-position:center"></div>`:`<div class="av ${c}">${esc((p.name||p.username||'?')[0].toUpperCase())}</div>`;
