const fit=(f,w,h,q)=>new Promise((ok,no)=>{const r=new FileReader;r.onload=()=>{const i=new Image;i.onload=()=>{const c=document.createElement('canvas');c.width=w;c.height=h;const k=Math.max(w/i.width,h/i.height),dw=i.width*k,dh=i.height*k;c.getContext('2d').drawImage(i,(w-dw)/2,(h-dh)/2,dw,dh);ok(c.toDataURL('image/jpeg',q))};i.onerror=()=>no(new Error('Не удалось прочитать изображение'));i.src=r.result};r.onerror=()=>no(new Error('Не удалось прочитать файл'));r.readAsDataURL(f)});
