S.db.collection('msgs').onSnapshot(s=>{S.msgs={};s.docs.forEach(d=>S.msgs[d.id]=d.data().list||[]);render()},()=>{});
if(S.me)S.db.doc('data/users/'+S.me.id+'/state').onSnapshot(s=>{S.st=s.exists?s.data():{};render()},()=>{});
S.db.collection('stars').onSnapshot(s=>{S.stars={};s.docs.forEach(d=>S.stars[d.id]=d.data().ids||[]);render()},()=>{});
